#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=7

CF="https://api.cloudflare.com/client/v4"

# jget <dotted.path> — read a value out of JSON on stdin (uses node, always present).
jget() {
  node -e '
    let d="";
    process.stdin.on("data", c => d += c).on("end", () => {
      try {
        let v = JSON.parse(d);
        for (const k of process.argv[1].split(".")) v = (v == null ? v : v[k]);
        process.stdout.write(v == null ? "" : String(v));
      } catch (e) { process.stdout.write(""); }
    });
  ' "$1"
}

# find_kv <title> — read {"result":[{id,title}]} on stdin, print id whose title matches.
find_kv() {
  node -e '
    let d="";
    process.stdin.on("data", c => d += c).on("end", () => {
      try {
        const a = (JSON.parse(d).result) || [];
        const hit = a.find(x => x.title === process.argv[1]);
        process.stdout.write(hit ? hit.id : "");
      } catch (e) { process.stdout.write(""); }
    });
  ' "$1"
}

# cf <METHOD> <path> [json-body]
cf() {
  local m="$1" p="$2" d="${3:-}"
  if [[ -n "$d" ]]; then
    curl -s -X "$m" "$CF$p" -H "Authorization: Bearer ${CF_API_TOKEN:-}" \
      -H "Content-Type: application/json" --data "$d"
  else
    curl -s -X "$m" "$CF$p" -H "Authorization: Bearer ${CF_API_TOKEN:-}"
  fi
}

banner "一键部署 karing 订阅到 Cloudflare"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "环境检查"
say "确认这台机器上需要的工具都在。"
missing=()
for t in node npx gh git curl; do
  if command -v "$t" >/dev/null 2>&1; then note "✓ $t"; else warn "✗ $t 未找到"; missing+=("$t"); fi
done
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  note "✓ gh 已登录：$(gh api user --jq .login 2>/dev/null || echo '?')"
else
  warn "gh 未登录；后面创建仓库 / 写 Secrets 会跳过。请先执行: gh auth login"
  SKIPPED+=("gh auth login")
fi
if (( ${#missing[@]} )); then
  warn "缺少工具: ${missing[*]} —— 装好后再重跑本脚本。"
  exit 1
fi
pause

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Cloudflare API Token"
say "需要一个能管理 Workers / KV 的 API Token。只需给一次，之后全自动。"
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "点「Create Token」→ 选模板「Edit Cloudflare Workers」→ Continue to summary → Create Token。"
step "复制生成的 Token（只显示一次）。若绑域名时提示权限不足，另建 Token 加上 Zone→DNS→Edit。"
ask_secret CF_API_TOKEN "粘贴 Token:"
resp=$(cf GET "/user/tokens/verify")
st=$(printf '%s' "$resp" | jget "result.status")
if [[ "$st" != "active" ]]; then
  warn "Token 校验失败: $resp"
  exit 1
fi
note "✓ Token 有效"
write_env CF_API_TOKEN "$CF_API_TOKEN"

resp=$(cf GET "/accounts")
acct=$(printf '%s' "$resp" | jget "result.0.id")
acct_name=$(printf '%s' "$resp" | jget "result.0.name")
if [[ -z "$acct" ]]; then
  warn "拿不到账户 ID: $resp"
  exit 1
fi
if [[ -n "$(_existing CF_ACCOUNT_ID || true)" ]]; then acct="$(_existing CF_ACCOUNT_ID)"; fi
say "账户: ${acct_name:-?}  ($acct)"
if confirm "用这个账户?"; then
  CF_ACCOUNT_ID="$acct"
else
  ask CF_ACCOUNT_ID "手动填 Account ID:"
fi
write_env CF_ACCOUNT_ID "$CF_ACCOUNT_ID"

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "创建 KV 命名空间"
say "存放订阅的键值空间（已存在则复用）。"
resp=$(cf GET "/accounts/$CF_ACCOUNT_ID/storage/kv/namespaces")
kvid=$(printf '%s' "$resp" | find_kv "karing-sub")
if [[ -z "$kvid" ]]; then
  note "未找到，正在创建…"
  resp=$(cf POST "/accounts/$CF_ACCOUNT_ID/storage/kv/namespaces" '{"title":"karing-sub"}')
  kvid=$(printf '%s' "$resp" | jget "result.id")
fi
if [[ -z "$kvid" ]]; then
  warn "创建/查找 KV 失败: $resp"
  exit 1
fi
CF_KV_NAMESPACE_ID="$kvid"
write_env CF_KV_NAMESPACE_ID "$kvid"
note "✓ KV 命名空间 karing-sub = $kvid"
pause

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "订阅域名"
say "订阅将通过你自己的域名提供 —— 这是国内能直连的关键。"
ask SUBDOMAIN "订阅子域名（如 sub.example.com）:"
zone="${SUBDOMAIN#*.}"
resp=$(cf GET "/zones?name=$zone")
zid=$(printf '%s' "$resp" | jget "result.0.id")
if [[ -z "$zid" ]]; then
  warn "在本账号下找不到域名 $zone（确认它已托管在此账号，且 Token 有 Zone 权限）。"
  confirm "仍要继续?" || exit 1
else
  note "✓ 域名 $zone 已在本账号"
fi
write_env SUBDOMAIN "$SUBDOMAIN"
sed -i "s|REPLACE_WITH_YOUR_KV_NAMESPACE_ID|$CF_KV_NAMESPACE_ID|g" cloudflare/wrangler.toml
sed -i "s|sub\.example\.com|$SUBDOMAIN|g" cloudflare/wrangler.toml
note "✓ 已写入 cloudflare/wrangler.toml"
pause

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "创建 GitHub 仓库并推送"
say "当前目录会初始化为 git 仓库，并推送到一个【公开】GitHub 仓库。"
ask REPO_NAME "仓库名:"
[[ -z "$REPO_NAME" ]] && REPO_NAME="free-vpn"
if [[ -d .git ]]; then
  note "已是 git 仓库"
else
  git init -q
  git branch -M main 2>/dev/null || true
fi
git add -A
git -c user.name="setup" -c user.email="setup@local" commit -q -m "init: karing region subscription" || note "无改动可提交"
owner=$(gh api user --jq .login 2>/dev/null || echo "")
if confirm "创建公开仓库 ${owner:-you}/$REPO_NAME 并推送?"; then
  if git remote get-url origin >/dev/null 2>&1; then
    git push -u origin main || warn "推送失败，请检查 remote"
  else
    gh repo create "$REPO_NAME" --public --source=. --remote=origin --push
  fi
fi
REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || echo "")
[[ -n "$REPO" ]] && note "✓ 仓库: $REPO"
write_env REPO "$REPO"
pause

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "配置 GitHub Secrets"
say "把 3 个 Cloudflare 值写进仓库 Secrets，供 Actions 使用。"
set_secret CF_ACCOUNT_ID "$CF_ACCOUNT_ID"
set_secret CF_KV_NAMESPACE_ID "$CF_KV_NAMESPACE_ID"
set_secret CF_API_TOKEN "$CF_API_TOKEN"
pause

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "部署 Worker 并首次运行"
say "部署只读 Worker、绑上域名，然后触发一次订阅生成。"
(
  cd cloudflare
  export CLOUDFLARE_API_TOKEN="$CF_API_TOKEN" \
         CLOUDFLARE_ACCOUNT_ID="$CF_ACCOUNT_ID" \
         WRANGLER_SEND_METRICS=false
  npx --yes wrangler@latest deploy
) && note "✓ Worker 已部署" || {
  warn "wrangler 部署失败：多半是 Token 缺 Zone 权限。"
  warn "可在控制台手动绑定：Workers → karing-sub → Settings → Domains & Routes → Add custom domain → $SUBDOMAIN"
}
say "触发一次订阅生成（GitHub Actions）…"
if gh workflow run update-sub.yml >/dev/null 2>&1; then
  note "✓ 已触发"
else
  warn "触发失败，可到仓库 Actions 页手动 Run workflow"
fi
note "首次要下载 GeoIP 库并生成，约 1–2 分钟。"

url="https://$SUBDOMAIN/sub"
say "等待订阅就绪（最多 ~3 分钟）：$url"
ready=""
for i in $(seq 1 18); do
  code=$(curl -s -o /dev/null -w '%{http_code}' "$url" 2>/dev/null || true)
  if [[ "$code" == "200" ]]; then ready="1"; note "✓ 订阅已就绪"; break; fi
  printf '  %s等待中… (%s/18)%s\n' "$DIM" "$i" "$RESET"
  sleep 10
done
[[ -z "$ready" ]] && warn "还没就绪：可能是首次构建较慢，或 Worker 域名未绑定。稍后手动打开上面的地址看看。"
open_url "$url"
pause "在 Karing 里添加这个订阅地址即可。按 Enter 结束。"
# ──────────────────────────────────────────────────────────────────────────

finish
